HB_RE = re.compile(r"(?:هيموغلوبين|هيموجلوبين|خضاب|Hb)\D{0,12}?(\d{1,2}(?:\.\d+)?)", re.I)
PROTEIN_GRADE_RE = re.compile(r"(?:بروتين(?:\s+البول)?|زلال)\D{0,10}?([0-4])\s*\+", re.I)
