# NOTE: `pregnancy_nutrition` was deliberately REMOVED from this set (2026-07-26).
# A general nutrition tip was enough to mark the patient as pregnant, which is part of
# gap ك-٤ (sticky/false pregnancy context). The label itself was merged into
# `nutrition` — see data/LABELING_GUIDE.md §2. Pregnancy context now comes from the
# patient record, not from a dietary sentence.
PREGNANCY_LABELS = {"pregnancy_risk"}
CRITICAL_LABELS = {"emergency", "pregnancy_risk", "allergy", "medication"}


def _should_emit_low_conf_critical(item: dict, label: str) -> bool:
    """Return whether a low-confidence critical label deserves an R10 safety fact.

    `pregnancy_risk` is a classifier class, not itself a diagnosis.  A sentence that
    merely establishes pregnancy/gestational age (e.g. "حامل بالأسبوع 34") must not
    become a critical warning just because the classifier chose that class with low
    confidence.  Keep R10 for pregnancy-risk sentences that contain actual clinical
    evidence or urgent language.
    """
    if not item.get("is_low_confidence") or label not in CRITICAL_LABELS:
        return False
    if label != "pregnancy_risk":
        return True

    links = item.get("entity_links") or []
    # If a deterministic extractor has already captured an explicit diagnosis phrase
    # (e.g. "معها سكر الحمل" -> condition:gdm), the low-confidence classifier class
    # is no longer the source of that clinical fact.  Emitting R10 would ask the
    # clinician to confirm a probabilistic label that the structured evidence already
    # established explicitly.  Urgent evidence is handled independently by R09.
    has_trusted_explicit_condition = any(
        isinstance(link, dict)
        and str(link.get("kind", "")) == "condition"
        and str(link.get("assertion", "present")) == "present"
        and float(link.get("confidence", 1.0) or 0.0) >= 0.90
        for link in links
    )
    if has_trusted_explicit_condition:
        return False
    if item.get("is_urgent"):
        return True

    # A low-confidence `pregnancy_risk` fragment can simply be a continuation of a
    # monitoring/contingency plan (e.g. "ونبض الجنين وحالة الأم بشكل مستمر").  Once
    # SOAP/discourse has established that role, do not ask the clinician to confirm a
    # spurious critical classifier label.  Genuine urgent plans were returned above.
    if str(item.get("soap_section", "")) == "plan":
        return False

    risk_kinds = {"symptom", "condition", "vital", "lab", "medication", "allergy", "clinical"}
    if any(
        isinstance(link, dict)
        and str(link.get("assertion", "present")) == "present"
        and str(link.get("kind", "")) in risk_kinds
        for link in links
    ):
        return True

    text = _norm(str(item.get("text", "")))
    gestational_context = bool(GA_WEEK_RE.search(text) or MONTH_RE.search(text) or TRIMESTER_RE.search(text))
    danger_markers = (
        "خطر", "تسمم", "نزيف", "نزف", "صداع", "تشوش", "مشوش", "ضغط", "زلال",
        "تورم", "انتفاخ", "ألم شديد", "الم شديد", "طوارئ", "عاجل", "فورا", "فوراً",
        "قلة حركة", "سكري حمل", "ولادة مبكرة",
    )
    if gestational_context and not any(marker in text for marker in danger_markers):
        return False
    return True


@dataclass
class Entity:
    kind: str            # symptom|vital|lab|test_done|diagnosis|medication|allergy|emergency|followup|low_conf
    code: str
    negated: bool = False
    value: Any = None                    # bool / number / string
    value2: Any = None                   # secondary numeric/string value
    unit: Optional[str] = None
    status: Optional[str] = None       # lab: high|low|normal
    item_id: str = ""
    report_index: int = 0
    text: str = ""
    confidence: float = 1.0
    soap_section: str = ""


@dataclass
class ReportExtraction:
    job_id: str
    index: int
    created_at: Optional[datetime]
    pregnant: bool = False
    ga_weeks: Optional[int] = None
    trimester: Optional[int] = None
    postpartum: bool = False
    labour: bool = False
    labour_stage: Optional[str] = None
    delivery: bool = False
    delivery_phase: Optional[str] = None
    entities: list[Entity] = field(default_factory=list)


def _norm(text: str) -> str:
    return str(text).translate(_ARABIC_INDIC).replace("ـ", "")


def _is_negated(text: str, start: int) -> bool:
    window = text[max(0, start - 35):start]
    return any(m in window for m in NEGATION_MARKERS)


def _surface_in_text(text: str, surface: str) -> bool:
    """Word-aware fallback matcher for drug lexicon entries.

    Prevents substring collisions such as ``حديد`` inside ``تحديد`` while allowing
    normal Arabic clitic/article prefixes (``والحديد`` / ``بالحديد``).
    """
    start = text.find(surface)
    while start >= 0:
        end = start + len(surface)
        after_ok = end >= len(text) or not text[end].isalnum()
        word_start = start
        while word_start > 0 and text[word_start - 1].isalnum():
            word_start -= 1
        prefix = text[word_start:start]
        before_ok = prefix in {"", "و", "ف", "ب", "ك", "ل", "ال", "وال", "فال", "بال", "كال", "لل"}
        if before_ok and after_ok:
            return True
        start = text.find(surface, start + 1)
    return False


def _is_leg_cramp_context(text: str, start: int) -> bool:
    """Return True when the word تشنجات refers to a localized leg cramp.

    Without this guard, phrases such as "تشنجات بالساق" were incorrectly
    extracted as generalized convulsions and triggered pregnancy danger rules.
    """
    window = text[max(0, start - 12):start + 40]
    return any(
        marker in window
        for marker in (
            "بالساق", "في الساق", "الساقين", "تشنجات الساق",
            "شد عضلي", "عضلات الساق", "بالرجل", "الرجلين",
        )
    )


def _normalize_bp(sys_v: float, dia_v: float) -> tuple[float, float]:
    # Levantine short form: "ضغط 11/7" means 110/70.
    if sys_v <= 25:
        sys_v, dia_v = sys_v * 10, dia_v * 10
    return sys_v, dia_v


def _iter_items(report: dict) -> list[dict]:
    """Return report items from either the project's SOAP shape or legacy sections."""
    items: list[dict] = []
    soap = report.get("soap") or {}
    if soap:
        for section_key, section in soap.items():
            for raw in section.get("items", []):
                item = dict(raw)
                item.setdefault("soap_section", section_key)
                items.append(item)
    else:
        # Compatibility with the earlier AraBERT JSON: {sections: {name: {items: [...]}}}
        order = 0
        for section_name, section in (report.get("sections") or {}).items():
            for raw in section.get("items", []):
                item = dict(raw)
                item.setdefault("item_id", f"{report.get('job_id', 'report')}-{order:04d}")
                item.setdefault("order_index", order)
                item.setdefault("soap_section", section.get("label", section_name))
                item.setdefault("label", section.get("label", ""))
                item.setdefault("confidence", 1.0)
                items.append(item)
                order += 1
    return sorted(items, key=lambda it: it.get("order_index", 0))


def _structured_fact_entities(report: dict, report_index: int) -> list[Entity]:
    """Read optional exact facts without changing the existing report sections.

    Supported forms:
      ``clinical_facts`` / ``structured_facts``: list of {code, value, ...}
      ``medical_record.structured_data``: dict of code -> value

    This is the preferred path for exact values such as proteinuria grade, parity,
    fetal heartbeat, previous obstetric history, and screening results.
    """
    out: list[Entity] = []
    record = report.get("medical_record") or {}
    raw_lists = [
        report.get("clinical_facts"), report.get("structured_facts"),
        record.get("clinical_facts"), record.get("structured_facts"),
    ]
    counter = 0
    for raw_list in raw_lists:
        if not isinstance(raw_list, list):
            continue
        for raw in raw_list:
            if not isinstance(raw, dict) or not raw.get("code"):
                continue
            code = str(raw["code"])
            out.append(Entity(
                kind="clinical", code=code, value=raw.get("value", True),
                value2=raw.get("value2"), unit=raw.get("unit"),
                status=raw.get("status"), negated=bool(raw.get("negated", False)),
                item_id=str(raw.get("item_id") or f"structured-{report_index}-{counter:03d}"),
                report_index=report_index, text=str(raw.get("text") or code),
                confidence=float(raw.get("confidence", 1.0)),
                soap_section=str(raw.get("soap_section", "structured")),
            ))
            counter += 1

    data = record.get("structured_data") or {}
    if isinstance(data, dict):
        for code, value in data.items():
            if isinstance(value, (dict, list)):
                continue
            out.append(Entity(
                kind="clinical", code=str(code), value=value,
                item_id=f"structured-{report_index}-{counter:03d}",
                report_index=report_index, text=f"{code}: {value}",
                confidence=1.0, soap_section="structured",
            ))
            counter += 1

    patient = report.get("patient_info") or {}
    age = patient.get("age_years", patient.get("age"))
    if age is not None:
        out.append(Entity(kind="clinical", code="maternal_age", value=age,
                          item_id=f"patient-{report_index}-age", report_index=report_index,
                          text=f"maternal_age: {age}", soap_section="patient_info"))
        try:
            if 15 <= float(age) <= 49:
                out.append(Entity(kind="clinical", code="reproductive_age", value=True,
                                  item_id=f"patient-{report_index}-reproductive-age",
                                  report_index=report_index, text=f"reproductive_age: {age}",
                                  soap_section="patient_info"))
        except (TypeError, ValueError):
            pass
    bmi = patient.get("bmi")
    if bmi is not None:
        try:
            out.append(Entity(kind="clinical", code="bmi", value=float(bmi), unit="kg/m2",
                              item_id=f"patient-{report_index}-bmi", report_index=report_index,
                              text=f"bmi: {bmi}", soap_section="patient_info"))
        except (TypeError, ValueError):
            pass
    return out


# Specific KBS findings that refine a broader entity produced by the application
# extractor. A refinement may be added only when the structured parent mention is
# asserted PRESENT; this preserves the app's richer hypothetical/history/family
# assertion handling while still giving source-derived KBS rules the specificity
# they need.
STRUCTURED_PARENT_CODES: dict[str, str] = {
    "severe_headache": "headache",
    "severe_abdominal_pain": "abdominal_pain",
    "foul_vaginal_discharge": "vaginal_discharge",
    "abnormal_vaginal_discharge": "vaginal_discharge",
    "curd_like_vaginal_discharge": "vaginal_discharge",
    "severe_vulvar_itching": "itching",
    "low_back_pain": "back_pain",
}


def _allow_structured_fallback(entity: Entity, links: list[dict]) -> bool:
    """Whether a text-derived entity may supplement structured ``entity_links``.

    Numeric/MD-specific facts are intentionally supplemented. Symptoms and
    diagnoses are stricter: they must be confirmed by a structured PRESENT entity
    (same code or a known broader parent). This prevents safety-netting advice,
    family history, historical findings, and planned actions from being promoted to
    current clinical facts by the simpler KBS text matcher.
    """
    if entity.kind == "lab":
        # A structured lab link is authoritative for that analyte.  Re-parsing the
        # same sentence can disagree on status/value (the exact Hb 9.5 production
        # failure that motivated V5), so only supplement *other* labs.
        if any(
            str(link.get("kind", "")) == "lab"
            and str(link.get("code", "")) == entity.code
            for link in links
        ):
            return False
    if entity.kind == "clinical" and entity.code == "hemoglobin_g_dl":
        # Current reports already carry the parsed haemoglobin value in entity_links.
        # Never re-parse the raw sentence and create a second competing numeric truth.
        if any(
            str(link.get("kind", "")) == "lab"
            and str(link.get("code", "")) == "hemoglobin"
            and str(link.get("assertion", "present")) == "present"
            and link.get("value") is not None
            for link in links
        ):
            return False
    if entity.kind == "clinical":
        # General single-source-of-truth rule: if the application extractor already
        # produced this numeric/boolean clinical code, do not re-parse the raw text in
        # the KBS adapter.  This now covers cervical_dilation_cm and labour discourse
        # facts as well as the earlier haemoglobin special case.
        if any(
            str(link.get("kind", "")) == "clinical"
            and str(link.get("code", "")) == entity.code
            and str(link.get("assertion", "present")) == "present"
            for link in links
        ):
            return False
    if entity.kind in {"vital", "lab", "test_done", "clinical"}:
        return True
    if entity.kind not in {"symptom", "diagnosis"}:
        return False

    target = STRUCTURED_PARENT_CODES.get(entity.code, entity.code)
    relevant = [
        link for link in links
        if str(link.get("code", "")) in {entity.code, target}
    ]
    if not relevant:
        return False
    return any(str(link.get("assertion", "present")) == "present" for link in relevant)


def entities_from_links(item: dict, report_index: int) -> list[Entity]:
    """Convert pre-computed entity_links into KBS entities."""
    links = item.get("entity_links") or []

    base = dict(
        item_id=item.get("item_id", ""),
        report_index=report_index,
        text=item.get("text", ""),
        confidence=float(item.get("confidence", 1.0)),
        soap_section=item.get("soap_section", ""),
    )

    kind_map = {
        "symptom": "symptom",
        "condition": "diagnosis",
        "test": "test_done",
        "lab": "lab",
        "medication": "medication",
        "allergy": "allergy",
        "vital": "vital",
        "procedure": "test_done",
        "nutrition": "nutrition",
        "clinical": "clinical",
        "history": "clinical",
        "screening": "clinical",
    }

    code_aliases = {
        "blood_pressure": "bp",
        "blood-pressure": "bp",
        "bloodPressure": "bp",
        "temperature": "temp",
    }

    out: list[Entity] = []

    for link in links:
        kind = kind_map.get(str(link.get("kind", "")))
        if kind is None:
            continue

        assertion = str(link.get("assertion", "present"))
        if assertion not in {"present", "absent"}:
            continue

        raw_code = str(link.get("code", ""))
        code = code_aliases.get(raw_code, raw_code)

        # Suspected diagnoses remain useful structured context without being promoted
        # to a confirmed DiagnosisNoted fact.  Postpartum infection in Scenario 5 is
        # explicitly phrased as "لازم نفكر...", so keep that epistemic status.
        if (
            kind == "diagnosis"
            and code == "puerperal_infection"
            and str(link.get("status", "")) == "suspected"
        ):
            out.append(Entity(
                kind="clinical", code="suspected_puerperal_infection",
                value=True, status="suspected", **base,
            ))
            continue

        # Suspected membrane rupture is clinically useful context, but it must not be
        # promoted to the confirmed `water_breaking` symptom because runner.py maps
        # that to rupture_of_membranes=True and would fire confirmed-ROM rules.
        if code == "water_breaking" and str(link.get("status", "")) == "suspected":
            out.append(
                Entity(
                    kind="clinical",
                    code="suspected_rupture_of_membranes",
                    value=True,
                    status="suspected",
                    **base,
                )
            )
            continue

        out.append(
            Entity(
                kind=kind,
                code=code,
                negated=(assertion == "absent"),
                value=link.get("value"),
                value2=link.get("value2"),
                unit=link.get("unit"),
                status=link.get("status"),
                **base,
            )
        )

        # Single source of truth for numeric haemoglobin: downstream MD-derived
        # rules historically consume `hemoglobin_g_dl` as a ClinicalFact.  Derive
        # that compatibility fact from the structured lab link instead of parsing
        # the sentence a second time.
        if (
            kind == "lab"
            and code == "hemoglobin"
            and assertion == "present"
            and link.get("value") is not None
        ):
            out.append(
                Entity(
                    kind="clinical",
                    code="hemoglobin_g_dl",
                    value=link.get("value"),
                    unit=link.get("unit") or "g/dL",
                    **base,
                )
            )

        if kind == "vital" and code == "bp" and assertion == "present":
            bp_test_base = dict(base)
            bp_test_base["item_id"] = (
                f"{base.get('item_id', '')}-bp-measurement"
            )

            out.append(
                Entity(
                    kind="test_done",
                    code="bp_measurement",
                    value=True,
                    negated=False,
                    **bp_test_base,
                )
            )

    # Cross-cutting item flags are not entity_links and must survive the structured
    # extraction path.  Without this, any item that had entity_links silently lost its
    # EmergencyFlag / LowConfidenceCritical facts, so R09/R10 could fail to fire.
    label = str(item.get("label", ""))
    # Current reports carry an explicit assertion-aware safety flag.  Do not turn an
    # `emergency` *topic* label into R09 when the sentence explicitly denies the danger
    # sign.  Legacy reports that lack the field keep the old fallback behaviour.
    urgent_flag = item.get("is_urgent")
    if urgent_flag is True or (urgent_flag is None and label == "emergency"):
        out.append(Entity(kind="emergency", code="emergency", **base))
    if label == "follow_up":
        out.append(Entity(kind="followup", code="follow_up", **base))
    if _should_emit_low_conf_critical(item, label):
        out.append(Entity(kind="low_conf", code=label, **base))

    return out

def extract_item(item: dict, report_index: int) -> list[Entity]:
    text = _norm(item.get("text", ""))
    label = item.get("label", "")
    base = dict(
        item_id=item.get("item_id", ""), report_index=report_index,
        text=item.get("text", ""), confidence=float(item.get("confidence", 1.0)),
        soap_section=item.get("soap_section", ""),
    )
    out: list[Entity] = []

    # --- symptoms (any label; classifier labels are hints, not gates) ---
    for code, variants in SYMPTOM_LEXICON.items():
        explicit = EXPLICIT_ABSENT.get(code, [])
        if any(p in text for p in explicit):
            out.append(Entity(kind="symptom", code=code, negated=True, **base))
            continue
        for phrase in variants:
            pos = text.find(phrase)
            if pos >= 0:
                # "تشنجات بالساق" means leg cramps, not generalized convulsions.
                if code == "convulsions" and _is_leg_cramp_context(text, pos):
                    continue

                out.append(
                    Entity(
                        kind="symptom",
                        code=code,
                        negated=_is_negated(text, pos),
                        **base,
                    )
                )
                break

    # --- vitals: BP + temperature (with numeric values) ---
    m = BP_RE.search(text)
    if m:
        sys_v, dia_v = _normalize_bp(float(m.group(1)), float(m.group(2)))
        out.append(Entity(kind="vital", code="bp", value=sys_v, value2=dia_v, **base))
        out.append(Entity(kind="test_done", code="bp_measurement", **base))
    m = TEMP_RE.search(text)
    if m:
        out.append(Entity(kind="vital", code="temp", value=float(m.group(1)), **base))
    m = HBA1C_RE.search(text)
    if m:
        v = float(m.group(1))
        out.append(Entity(kind="lab", code="hba1c", value=v,
                          status="high" if v >= 6.5 else "normal", **base))
        out.append(Entity(kind="test_done", code="hba1c_test", **base))

    # --- labs by lexicon ---
    for code, (variants, implied_test) in LAB_LEXICON.items():
        for phrase in variants:
            pos = text.find(phrase)
            if pos >= 0 and not _is_negated(text, pos):
                status = ("high" if any(h in text for h in HIGH_MARKERS)
                          else "low" if any(low in text for low in LOW_MARKERS) else "normal")
                out.append(Entity(kind="lab", code=code, status=status, **base))
                out.append(Entity(kind="test_done", code=implied_test, **base))
                break

    # --- tests explicitly done/ordered ---
    for code, variants in TEST_DONE_LEXICON.items():
        if any(p in text for p in variants):
            out.append(Entity(kind="test_done", code=code, **base))

    # --- diagnoses ---
    for code, variants in DIAGNOSIS_LEXICON.items():
        for phrase in variants:
            pos = text.find(phrase)
            if pos >= 0 and not _is_negated(text, pos):
                out.append(Entity(kind="diagnosis", code=code, **base))
                break

    # --- drugs: allergy vs medication decided by the classifier label ---
    if label in {"allergy", "medication", "treatment"}:
        kind = "allergy" if label == "allergy" else "medication"
        found = set()
        for code, variants in DRUG_LEXICON.items():
            if any(_surface_in_text(text, p) for p in variants):
                found.add(code)
        for tok in _LATIN_TOKEN.findall(text):
            low = tok.lower()
            if low not in _LATIN_STOP and low not in found:
                # unknown Latin token in a drug/allergy sentence -> treat as drug code
                if not any(low in [v.lower() for v in vs] for vs in DRUG_LEXICON.values()):
                    found.add(low)
        for code in found:
            out.append(Entity(kind=kind, code=code, **base))

    # --- generic clinical flags used by the MD-derived rules ---
    for code, variants in CLINICAL_FACT_LEXICON.items():
        for phrase in variants:
            pos = text.find(phrase)
            if pos >= 0:
                out.append(Entity(kind="clinical", code=code,
                                  value=not _is_negated(text, pos),
                                  negated=_is_negated(text, pos), **base))
                break

    # --- infertility rules from the sixth source file ---
    # The full source condition is used as a canonical natural-language pattern.
    # It is intentionally independent of classifier labels and requires no extra
    # medical_record or clinical_facts field in the AraBERT JSON.
    for code, variants in FOLLOW6_TRIGGER_LEXICON.items():
        for phrase in variants:
            if phrase and phrase in text:
                out.append(Entity(kind="clinical", code=code, value=True, **base))
                break

    # --- postpartum and newborn rules from the seventh source file ---
    # Full source conditions are canonical SOAP patterns. This requires no
    # medical_record, clinical_facts, structured_facts, or entity_links data.
    for code, variants in FOLLOW7_TRIGGER_LEXICON.items():
        for phrase in variants:
            if phrase and phrase in text:
                out.append(Entity(kind="clinical", code=code, value=True, **base))
                break

    # Exact numeric facts when explicitly documented in the sentence.
    m = HB_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="hemoglobin_g_dl",
                          value=float(m.group(1)), unit="g/dL", **base))
    m = PROTEIN_GRADE_RE.search(text)
    if m:
        protein_grade = int(m.group(1))

        out.append(
            Entity(
                kind="clinical",
                code="proteinuria_grade",
                value=protein_grade,
                unit="plus",
                **base,
            )
        )

        # A documented proteinuria result means the urine-protein test was done.
        out.append(
            Entity(
                kind="lab",
                code="urine_protein",
                value=protein_grade,
                unit="plus",
                status="high" if protein_grade >= 1 else "normal",
                **base,
            )
        )
        out.append(
            Entity(
                kind="test_done",
                code="urine_protein_test",
                value=True,
                **base,
            )
        )
    m = RESP_RATE_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="respiratory_rate",
                          value=int(m.group(1)), unit="breaths/min", **base))
    m = PARITY_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="parity", value=int(m.group(1)), **base))
    m = CERVICAL_DILATION_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="cervical_dilation_cm",
                          value=float(m.group(1)), unit="cm", **base))
    m = FETAL_HEART_RATE_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="fetal_heart_rate_bpm",
                          value=int(m.group(1)), unit="bpm", **base))
    m = LATENT_DURATION_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="latent_stage_duration_hours",
                          value=float(m.group(1)), unit="hours", **base))
    m = ACTIVE_DURATION_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="active_stage_duration_hours",
                          value=float(m.group(1)), unit="hours", **base))
    m = DILATION_RATE_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="cervical_dilation_rate_cm_per_hour",
                          value=float(m.group(1)), unit="cm/hour", **base))

    numeric_patterns = (
        (FASTING_GLUCOSE_RE, "fasting_glucose_mmol_l", "mmol/L"),
        (OGTT_1H_RE, "ogtt_1h_glucose_mmol_l", "mmol/L"),
        (OGTT_2H_RE, "ogtt_2h_glucose_mmol_l", "mmol/L"),
        (RANDOM_GLUCOSE_RE, "random_glucose_mmol_l", "mmol/L"),
        (CAFFEINE_RE, "daily_caffeine_mg", "mg/day"),
        (BMI_RE, "bmi", "kg/m2"),
        (ANEMIA_PREVALENCE_RE, "community_anemia_prevalence_percent", "percent"),
        (TB_INCIDENCE_RE, "tb_incidence_per_100k", "per_100k"),
    )
    for pattern, code, unit in numeric_patterns:
        m = pattern.search(text)
        if m:
            out.append(Entity(
                kind="clinical", code=code, value=float(m.group(1)), unit=unit, **base
            ))

    m = INFERTILITY_MONTHS_RE.search(text)
    if m:
        out.append(Entity(kind="clinical", code="infertility_attempt_months",
                          value=float(m.group(1)), unit="months", **base))
    else:
        m = INFERTILITY_YEARS_RE.search(text)
        if m:
            out.append(Entity(kind="clinical", code="infertility_attempt_months",
                              value=float(m.group(1)) * 12, unit="months", **base))

    lower = text.lower()
    if "rpr" in lower:
        if any(x in text for x in ("إيجابي", "موجب", "positive")):
            out.append(Entity(kind="clinical", code="rpr_positive", value=True, **base))
        elif any(x in text for x in ("سلبي", "negative")):
            out.append(Entity(kind="clinical", code="rpr_negative", value=True, **base))
    if "hiv" in lower or "فيروس نقص المناعة" in text:
        if any(x in text for x in ("إيجابي", "موجب", "positive", "مصابة")):
            out.append(Entity(kind="clinical", code="hiv_positive", value=True, **base))
        elif any(x in text for x in ("سلبي", "negative")):
            out.append(Entity(kind="clinical", code="hiv_negative", value=True, **base))

    # --- cross-cutting flags ---
    # Current reports carry an explicit assertion-aware safety flag.  Do not turn an
    # `emergency` *topic* label into R09 when the sentence explicitly denies the danger
    # sign.  Legacy reports that lack the field keep the old fallback behaviour.
    urgent_flag = item.get("is_urgent")
    if urgent_flag is True or (urgent_flag is None and label == "emergency"):
        out.append(Entity(kind="emergency", code="emergency", **base))
    if label == "follow_up":
        out.append(Entity(kind="followup", code="follow_up", **base))
    if _should_emit_low_conf_critical(item, label):
        out.append(Entity(kind="low_conf", code=label, **base))

    return out


def extract_report(report: dict, index: int = 0) -> ReportExtraction:
    created = report.get("created_at")
    created_dt = None
    if created:
        try:
            created_dt = datetime.fromisoformat(str(created).replace("Z", "+00:00"))
        except ValueError:
            created_dt = None

    ext = ReportExtraction(job_id=report.get("job_id", f"report{index}"),
                           index=index, created_at=created_dt)
    all_text = _norm(" ".join(it.get("text", "") for it in _iter_items(report)))
    medical_record = report.get("medical_record") or {}
    patient_info = report.get("patient_info") or {}

    # --- patient context ---
    # ``medical_record`` is optional. The normal AraBERT output can be consumed
    # unchanged; when metadata is absent, infer stage from SOAP text.
    labels = {it.get("label") for it in _iter_items(report)}
    stage = str(medical_record.get("clinical_stage", "")).lower().strip()
    raw_labour_stage = str(medical_record.get("labour_stage", "")).lower().strip()
    raw_delivery_phase = str(medical_record.get("delivery_phase", "")).lower().strip()

    def has_any(markers: list[str]) -> bool:
        return any(marker in all_text for marker in markers)

    cervical_match = CERVICAL_DILATION_RE.search(all_text)
    cervical_cm = float(cervical_match.group(1)) if cervical_match else None

    inferred_discharge = has_any(DISCHARGE_PHASE_MARKERS)
    inferred_postpartum = has_any(POSTPARTUM_MARKERS) or "postpartum" in labels

    # Explicit metadata wins. Otherwise use the most advanced strong stage marker.
    if raw_delivery_phase in {"second", "third", "newborn", "postpartum", "discharge"}:
        ext.delivery_phase = raw_delivery_phase
    elif stage in {"discharge", "predischarge"} or inferred_discharge:
        ext.delivery_phase = "discharge"
    elif stage in {"postpartum", "postpartum_follow_up"} or inferred_postpartum:
        ext.delivery_phase = "postpartum"
    elif stage == "newborn" or has_any(NEWBORN_PHASE_MARKERS):
        ext.delivery_phase = "newborn"
    elif stage == "third_stage" or has_any(THIRD_STAGE_MARKERS):
        ext.delivery_phase = "third"
    elif (
        stage in {"delivery", "birth", "second_stage"}
        or has_any(SECOND_STAGE_MARKERS)
        or (cervical_cm is not None and cervical_cm >= 10)
    ):
        ext.delivery_phase = "second"

    ext.delivery = (
        stage in {
            "delivery", "birth", "second_stage", "third_stage", "newborn",
            "postpartum", "postpartum_follow_up", "discharge", "predischarge",
        }
        or ext.delivery_phase is not None
    )
    ext.postpartum = (
        stage in {"postpartum", "postpartum_follow_up", "discharge", "predischarge"}
        or inferred_postpartum
        or ext.delivery_phase in {"postpartum", "discharge"}
    )

    explicit_labour = stage in {
        "labour", "labor", "intrapartum", "active_labour", "latent_labour",
    }
    inferred_labour = has_any(LABOUR_CONTEXT_MARKERS) or cervical_cm is not None

    ext.labour = explicit_labour or (
        inferred_labour
        and ext.delivery_phase not in {
            "second", "third", "newborn", "postpartum", "discharge",
        }
    )

    if raw_labour_stage in {"latent", "active", "second"}:
        ext.labour_stage = raw_labour_stage
    elif stage == "latent_labour":
        ext.labour_stage = "latent"
    elif stage == "active_labour":
        ext.labour_stage = "active"
    elif ext.labour:
        if has_any(ACTIVE_LABOUR_MARKERS):
            ext.labour_stage = "active"
        elif has_any(LATENT_LABOUR_MARKERS):
            ext.labour_stage = "latent"
        elif cervical_cm is not None:
            if cervical_cm >= 10:
                ext.labour_stage = "second"
            elif cervical_cm >= 5:
                ext.labour_stage = "active"
            else:
                ext.labour_stage = "latent"

    antenatal_hint = (
        stage == "pregnancy"
        or has_any(PREGNANT_MARKERS)
        or bool(labels & PREGNANCY_LABELS)
    )
    # PatientContext(pregnant=True) activates antenatal rules, so suppress it
    # during labour/delivery/postpartum.
    ext.pregnant = (
        stage == "pregnancy"
        or (
            antenatal_hint
            and not ext.labour
            and not ext.delivery
            and not ext.postpartum
        )
    )

    # The service's longitudinal PatientState is authoritative when present.
    # It prevents an old pregnancy mention in the report series from making the
    # current visit pregnant forever. Labour/delivery/postpartum stage markers still
    # suppress antenatal activation.
    effective_status = str(
        patient_info.get("effective_obstetric_status")
        or medical_record.get("effective_obstetric_status")
        or ""
    ).lower()
    if effective_status == "postpartum":
        ext.postpartum = True
        ext.pregnant = False
    elif effective_status == "pregnant" and not (ext.labour or ext.delivery or ext.postpartum):
        ext.pregnant = True
    elif effective_status in {"unknown", "not_pregnant"}:
        ext.pregnant = False

    structured_ga = patient_info.get("gestational_age_weeks")
    if structured_ga is None:
        structured_ga = medical_record.get("gestational_age_weeks")
    if structured_ga is not None:
        try:
            ext.ga_weeks = int(structured_ga)
        except (TypeError, ValueError):
            ext.ga_weeks = None
    m = GA_WEEK_RE.search(all_text)
    if ext.ga_weeks is None and m:
        ext.ga_weeks = int(m.group(1))
    elif ext.ga_weeks is None:
        mm = MONTH_RE.search(all_text)
        if mm and mm.group(1) in MONTH_TO_WEEKS:
            ext.ga_weeks = MONTH_TO_WEEKS[mm.group(1)]
    mt = TRIMESTER_RE.search(all_text)
    if mt and mt.group(1) in TRIMESTER:
        ext.trimester = TRIMESTER[mt.group(1)]
    if ext.ga_weeks and not ext.trimester:
        ext.trimester = 1 if ext.ga_weeks <= 13 else 2 if ext.ga_weeks <= 27 else 3

    # Prefer pre-computed entity_links when present, but supplement numeric
    # vitals/labs and MD-rule-specific clinical facts from the SOAP text.
    ext.entities.extend(_structured_fact_entities(report, index))
    items = _iter_items(report)

    for item in items:
        # A segment flagged by Whisper as a possible hallucination remains visible in
        # the report but is NOT allowed to become an actionable clinical fact. A
        # low-confidence fact is emitted instead so rule R10 can request review.
        if item.get("is_asr_suspect"):
            label = str(item.get("label", ""))
            if label in CRITICAL_LABELS or item.get("is_urgent") or item.get("is_low_confidence"):
                ext.entities.append(Entity(
                    kind="low_conf", code=label or "asr_suspect",
                    item_id=str(item.get("item_id", "")), report_index=index,
                    text=str(item.get("text", "")),
                    confidence=float(item.get("combined_confidence") or item.get("confidence") or 0.0),
                    soap_section=str(item.get("soap_section", "")),
                ))
            continue

        links = item.get("entity_links") or []
        if links:
            linked_entities = entities_from_links(item, index)
            ext.entities.extend(linked_entities)

            existing = {
                (
                    entity.kind,
                    entity.code,
                    entity.negated,
                    str(entity.value),
                    str(entity.value2),
                    entity.status,
                )
                for entity in linked_entities
            }

            for entity in extract_item(item, index):
                if not _allow_structured_fallback(entity, links):
                    continue

                key = (
                    entity.kind,
                    entity.code,
                    entity.negated,
                    str(entity.value),
                    str(entity.value2),
                    entity.status,
                )
                if key not in existing:
                    ext.entities.append(entity)
                    existing.add(key)
        else:
            # Backward compatibility for old JSON exports that pre-date entity_links.
            ext.entities.extend(extract_item(item, index))

    return ext